import numpy as np
from scipy.optimize import least_squares
def model(p):
    a0,k,c,F,w,ph,k3=p
    return a0 - k*x - c*v + F*np.cos(w*t+ph) - k3*x**3
best=None
for w0 in np.linspace(0.2,6,30):
    for ph0 in [0,1.5,3]:
        try:
            r=least_squares(lambda p: model(p)-dv_dt,[0,1,0.5,1,w0,ph0,0])
            if best is None or r.cost<best.cost: best=r
        except Exception as e: pass
print(best.x.round(4), "NMSE", np.mean(best.fun**2)/np.var(dv_dt))

import numpy as np
def basis(w):
    return np.column_stack([np.ones_like(x),x,v,x**3,v*np.abs(v),x*v,np.cos(w*t),np.sin(w*t)])
res=[]
for w in np.arange(0.05,8,0.005):
    A=basis(w)
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    res.append((np.mean((dv_dt-A@c)**2)/np.var(dv_dt),w))
res.sort()
print(res[:8])
